            data.put("status", skillPackage.getStatus());
            data.put("originalFilename", skillPackage.getOriginalFilename());
            data.put("createdAt", formatDateTime(skillPackage.getCreatedAt()));
            data.put("parsedAt", formatDateTime(skillPackage.getParsedAt()));
            return ResponseEntity.ok(ApiResponse.success(data));
        } catch (PackageService.PackageNotFoundException e) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(ApiResponse.<Map<String, Object>>error(404, "Package not found"));
        } catch (PackageService.AccessDeniedException e) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
